  @Test void tutorRevalidatesAndLocksCitedResourcesAtCommit() throws Exception {long student=user("resource_commit"),uploader=user("resource_commit_uploader");AuthenticatedUser principal=student(student);long resource=id("INSERT INTO edu_teaching_resource(course_id,title,resource_type,external_url,review_status,uploader_id) VALUES(1,'approved','EXTERNAL_LINK','https://approved.example/resource','APPROVED',?)",uploader);jdbc.update("INSERT INTO edu_resource_knowledge_point(resource_id,knowledge_point_id) VALUES(?,'kp')",resource);when(graph.ragContext(1L, "kp")).thenReturn(new InternalGraphRagContextResponse(1L, node("kp"), List.of(), List.of(), List.of(), "g", "READY", List.of()));var session=tutor.create(principal,new TutorSessionCreateRequest(1L, "kp", TutorEntrySource.MANUAL, null));CountDownLatch validatedResource=new CountDownLatch(1),releaseValidation=new CountDownLatch(1);List<AiCognitiveLabel> blockingLabels=new AbstractList<>(){int calls;public AiCognitiveLabel get(int index){throw new IndexOutOfBoundsException();}public int size(){if(++calls==2){validatedResource.countDown();await(releaseValidation);}return 0;}};doAnswer(inv->{var req=(AiTutorChatRequest)inv.getArgument(0);return new AiTutorChatResponse(1L, req.requestId(), "kp", "answer", List.of(new AiTutorContentBlock("image","caption",resource,"image",null,Map.of())), List.of(Map.of("resource_id",resource,"title","approved","reviewed",true,"review_status","APPROVED","rights_status","ALLOWED")), blockingLabels, null, "model", "prompt");}).when(ai).tutorChat(any());ExecutorService pool=Executors.newSingleThreadExecutor();try{Future<?> send=pool.submit(()->tutor.sendMessage(principal,session.id(),"c5-resource-commit-key","show"));assertThat(validatedResource.await(5,TimeUnit.SECONDS)).isTrue();jdbc.update("UPDATE edu_teaching_resource SET review_status='PENDING' WHERE id=?",resource);releaseValidation.countDown();assertThatThrownBy(()->send.get(5,TimeUnit.SECONDS)).isInstanceOfSatisfying(ExecutionException.class,e->assertThat(e.getCause()).isInstanceOfSatisfying(BusinessException.class,b->assertThat(b.errorCode()).isEqualTo(com.education.agent.common.error.ErrorCode.CONCURRENT_MODIFICATION)));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM edu_tutor_message WHERE session_id=?",Integer.class,session.id())).isZero();}finally{releaseValidation.countDown();pool.shutdownNow();}}

